package app.rwun;
import android.app.*;import android.content.*;import android.location.LocationManager;import android.os.*;import android.widget.*;import java.time.*;import org.json.*;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;import org.robolectric.shadows.*;import org.robolectric.util.ReflectionHelpers;
import static org.junit.Assert.*;
/** Real Android Views/framework storage with synthetic data; not hardware playback evidence. */
@RunWith(RobolectricTestRunner.class) @Config(sdk=35,qualifiers="w393dp-h852dp-mdpi",manifest=Config.NONE) @GraphicsMode(GraphicsMode.Mode.NATIVE) @LooperMode(LooperMode.Mode.PAUSED)
public class VoiceCoachTest {
 Application app;RunStore store;
 @Before public void setup(){app=RuntimeEnvironment.getApplication();app.getSharedPreferences("rwun",0).edit().clear().commit();app.getSharedPreferences(DailyHealthStore.FILE,0).edit().clear().commit();android.provider.Settings.Global.putInt(app.getContentResolver(),android.provider.Settings.Global.BOOT_COUNT,1);store=new RunStore(app);}
 org.robolectric.android.controller.ActivityController<VoiceCoachActivity> open(String page){return Robolectric.buildActivity(VoiceCoachActivity.class,new Intent().putExtra("screen",page)).setup().visible();}
 void click(Activity a,String label){NativePlanningTest.click(a,label);}
 void idle(){Shadows.shadowOf(Looper.getMainLooper()).idle();}
 @Test public void emptyBaselineAndRealDefinitionRender()throws Exception{try(var a=open("home")){String text=ProgressUiTest.all(a.get().getWindow().getDecorView());assertTrue(text.contains("baseline"));assertTrue(text.contains(BeginnerProgramme.describe(0)));NativePlanningTest.shot(a.get(),"voice-coach-baseline");}}
 @Test public void preferencesPersistAndHeartAlertsAreOptIn()throws Exception{try(var a=open("settings")){assertEquals(0,CoachingMemory.settings(store).heartLimit());click(a.get(),"Save voice preferences");assertEquals(VoiceGuidance.Mode.STANDARD,CoachingMemory.settings(store).mode());a.recreate();assertTrue(ProgressUiTest.all(a.get().getWindow().getDecorView()).contains("Health Connect history is not a live feed"));NativePlanningTest.shot(a.get(),"voice-coach-preferences");}}
 @Test public void rejectedPreviewDoesNotCreateHistory(){try(var a=open("home")){click(a.get(),"Preview next stage");assertNull(store.latestCoachChange());assertTrue(ProgressUiTest.all(a.get().getWindow().getDecorView()).contains("three manageable sessions"));}}
 @Test public void stageApplyAndUndoAreReviewedAndKeepActivities()throws Exception{for(int i=0;i<3;i++)store.add(new RunStore.Run("beginner:0:"+i,LocalDate.now().minusDays(6-i*2).toString(),3,24,4,2,false,"GPS","",0,1440),new JSONObject().put("stage",0).put("complete",true).put("manageable",true));try(var a=open("home")){click(a.get(),"Preview next stage");AlertDialog dialog=(AlertDialog)ShadowDialog.getLatestDialog();assertTrue(ProgressUiTest.all(dialog.getWindow().getDecorView()).contains("CURRENT"));assertNull(store.latestCoachChange());dialog.getButton(-1).performClick();idle();assertEquals(1,CoachingMemory.stage(store));click(a.get(),"Stage changes & undo");NativePlanningTest.shot(a.get(),"voice-coach-stage-history");click(a.get(),"Review undo of latest stage change");((AlertDialog)ShadowDialog.getLatestDialog()).getButton(-1).performClick();idle();assertEquals(0,CoachingMemory.stage(store));assertEquals(3,store.runs().size());}}
 @Test public void painCheckinPersistsAndStartsNoRecording(){try(var a=open("home")){click(a.get(),"Review & start beginner session");AlertDialog dialog=(AlertDialog)ShadowDialog.getLatestDialog();CheckBox pain=NativePlanningTest.find(dialog.getWindow().getDecorView(),"Pain or injury symptoms");assertNotNull(pain);pain.setChecked(true);dialog.getButton(-1).performClick();idle();assertTrue(new RunStore(app).resting());assertTrue(store.checkpoint().isEmpty());assertNull(Shadows.shadowOf(a.get()).getNextStartedActivity());}}
 @Test public void holdAndLargeFontsRender()throws Exception{store.coachCheckin(4,true);RuntimeEnvironment.setFontScale(1.6f);try(var a=open("home")){assertTrue(ProgressUiTest.all(a.get().getWindow().getDecorView()).contains("Training is on hold"));NativePlanningTest.shot(a.get(),"voice-coach-large-font");}finally{RuntimeEnvironment.setFontScale(1f);}}
 @Test public void beginnerIndoorDefinitionSurvivesRecreation()throws Exception{IndoorState.start(app,"Run",24,"beginner:0:test",false);assertEquals(BeginnerProgramme.workout(0).steps(),IndoorCoaching.definition(new RunStore(app),IndoorState.active(app)).steps());Shadows.shadowOf(Looper.getMainLooper()).idleFor(Duration.ofSeconds(300));IndoorCoaching.catchUp(app);assertEquals(1,IndoorState.active(app).getInt("step"));try(var a=Robolectric.buildActivity(IndoorActivity.class).setup().visible()){assertTrue(ProgressUiTest.all(a.get().getWindow().getDecorView()).contains("Comfortable run 1 of 6"));a.recreate();assertEquals(1,IndoorState.active(app).getInt("step"));}}
 @Test public void recoveredReceiptAndPainHoldPersistTogether()throws Exception{store.checkpoint(new JSONObject().put("id","beginner:0:interrupted").put("coachStage",0).put("workoutComplete",true).toString());store.add(new RunStore.Run("beginner:0:interrupted",LocalDate.now().toString(),2,24,4,2,true,"GPS","",0,1440),store.recordingReview("beginner:0:interrupted",true,true));assertTrue(new RunStore(app).resting());assertEquals(0,CoachingMemory.entries(new RunStore(app)).get(0).stage());}
 void permissions(){Shadows.shadowOf(app).grantPermissions(android.Manifest.permission.ACCESS_FINE_LOCATION,android.Manifest.permission.ACCESS_COARSE_LOCATION,android.Manifest.permission.POST_NOTIFICATIONS);Shadows.shadowOf(app.getSystemService(LocationManager.class)).setProviderEnabled(LocationManager.GPS_PROVIDER,true);}
 @Test public void audioInterruptionAndMuteClearPendingAdvice()throws Exception{permissions();var controller=Robolectric.buildService(TrackingService.class).create();try{var service=controller.get();android.speech.tts.TextToSpeech tts=ReflectionHelpers.getField(service,"speech");ShadowTextToSpeech.addLanguageAvailability(java.util.Locale.UK);Shadows.shadowOf(tts).getOnInitListener().onInit(android.speech.tts.TextToSpeech.SUCCESS);tts.setOnUtteranceProgressListener(new android.speech.tts.UtteranceProgressListener(){public void onStart(String id){}public void onDone(String id){}public void onError(String id){}});service.onStartCommand(new Intent(app,TrackingService.class).setAction("START").putExtra("id","beginner:0:audio"),0,1);Shadows.shadowOf(Looper.getMainLooper()).idleFor(Duration.ofSeconds(1));assertTrue(service.startFailure(),service.active());SpeechQueue.Cue playing=ReflectionHelpers.getField(service,"playingCue");assertNotNull(playing);assertEquals(SpeechQueue.Kind.PHASE,playing.kind());android.media.AudioManager.OnAudioFocusChangeListener listener=ReflectionHelpers.getField(service,"audioFocusListener");listener.onAudioFocusChange(android.media.AudioManager.AUDIOFOCUS_LOSS_TRANSIENT);SpeechQueue queue=ReflectionHelpers.getField(service,"speechQueue");assertEquals(0,queue.size());assertNull(ReflectionHelpers.getField(service,"playingCue"));service.repeatCue();assertNotNull(ReflectionHelpers.getField(service,"playingCue"));store.audio(false);Shadows.shadowOf(Looper.getMainLooper()).idleFor(Duration.ofSeconds(1));assertNull(ReflectionHelpers.getField(service,"playingCue"));assertEquals(0,queue.size());service.discard();}finally{controller.destroy();}}
 @Test public void recoveryHoldPausesActiveRecorder()throws Exception{store.audio(false);permissions();var controller=Robolectric.buildService(TrackingService.class).create();try{var service=controller.get();service.onStartCommand(new Intent(app,TrackingService.class).setAction("START").putExtra("id","beginner:0:hold"),0,1);Shadows.shadowOf(Looper.getMainLooper()).idleFor(Duration.ofSeconds(1));store.coachCheckin(2,true);Shadows.shadowOf(Looper.getMainLooper()).idleFor(Duration.ofSeconds(1));assertTrue(service.paused());assertTrue(store.resting());JSONObject cp=new JSONObject(store.checkpoint());assertEquals(0,cp.getInt("coachStage"));assertFalse(cp.getBoolean("workoutComplete"));try{service.togglePause();fail("Hold must block resume");}catch(IllegalStateException expected){}service.discard();}finally{controller.destroy();}}
 @Test public void savedRunReflectionPreservesTotals()throws Exception{store.add(new RunStore.Run("saved:reflection",LocalDate.now().toString(),5,40,5,2,false,"Manual","",0,2400));try(var a=open("reflect")){click(a.get(),LocalDate.now()+" · "+PlanEngine.distance(5)+" · Unstructured");((AlertDialog)ShadowDialog.getLatestDialog()).getButton(-1).performClick();idle();assertEquals(5,store.runs().get(0).km(),0);assertEquals(2400,store.runs().get(0).seconds());assertEquals(-1,CoachingMemory.entries(store).get(0).stage());assertTrue(ProgressUiTest.all(a.get().getWindow().getDecorView()).contains("Reflection saved"));}}
 @Test public void timeOnlyBeginnerCompletionSavesReviewedEvidence()throws Exception{
  store.audio(false);IndoorState.start(app,"Run",24,"beginner:0:complete",false);
  ShadowSystemClock.advanceBy(Duration.ofSeconds(BeginnerProgramme.totalSeconds(0)));IndoorCoaching.catchUp(app);
  try(var a=Robolectric.buildActivity(IndoorActivity.class).setup().visible()){
   assertTrue(ProgressUiTest.all(a.get().getWindow().getDecorView()).contains("Workout steps complete"));
   click(a.get(),"Finish and review");AlertDialog dialog=(AlertDialog)ShadowDialog.getLatestDialog();
   android.view.View label=NativePlanningTest.find(dialog.getWindow().getDecorView(),"Was the session manageable?");assertNotNull(label);
   android.view.ViewGroup form=(android.view.ViewGroup)label.getParent();((Spinner)form.getChildAt(form.indexOfChild(label)+1)).setSelection(1);
   dialog.getButton(-1).performClick();idle();assertNull(IndoorState.active(app));assertTrue(store.runs().isEmpty());
   var evidence=CoachingMemory.entries(store);assertEquals(1,evidence.size());assertEquals(0,evidence.get(0).stage());assertTrue(evidence.get(0).complete());assertEquals(Boolean.TRUE,evidence.get(0).manageable());assertEquals(0,evidence.get(0).km(),0);
  }
 }

 void privateRecovery(){var d=DailyHealthRules.defaults();new DailyHealthStore(app).settings(new DailyHealthRules.Settings(false,true,d.days(),d.startMinute(),d.endMinute(),d.inactivityMinutes(),d.breakMinutes()),Instant.now());}
 @Test public void privateRecoveryDoesNotDuplicateOrExportCoachCheckin(){privateRecovery();try(var a=open("home")){click(a.get(),"Review & start beginner session");AlertDialog dialog=(AlertDialog)ShadowDialog.getLatestDialog();assertNull(NativePlanningTest.find(dialog.getWindow().getDecorView(),"Fatigue today · 1 fresh, 5 exhausted"));dialog.getButton(-1).performClick();idle();assertFalse(CoachingMemory.data(store).has("checkin"));assertEquals(MainActivity.class.getName(),Shadows.shadowOf(a.get()).getNextStartedActivity().getComponent().getClassName());}}
 @Test public void privateRecoveryReturnKeepsBeginnerWorkoutIntent()throws Exception{
  privateRecovery();permissions();store.audio(false);var voice=Robolectric.buildService(TrackingService.class).create();
  Shadows.shadowOf(app).setComponentNameAndServiceForBindService(new ComponentName(app,TrackingService.class),voice.get().onBind(new Intent()));
  try(var a=Robolectric.buildActivity(MainActivity.class,new Intent().putExtra("destination","Run").putExtra("coachStart","beginner:0:private-return")).setup().visible()){
   idle();assertFalse(voice.get().active());assertNotNull(NativePlanningTest.find(a.get().getWindow().getDecorView(),"Continue beginner session"));
   new DailyHealthStore(app).saveCheckin(new DailyHealthRules.Checkin(Instant.now(),null,2,1,DailyHealthRules.Answer.UNKNOWN,DailyHealthRules.Answer.UNKNOWN,false));
   ((AlertDialog)ShadowDialog.getLatestDialog()).dismiss();click(a.get(),"Continue beginner session");
   Intent started=null,next;while((next=Shadows.shadowOf(app).getNextStartedService())!=null){if(next.getComponent()!=null&&TrackingService.class.getName().equals(next.getComponent().getClassName())&&"START".equals(next.getAction())){started=next;break;}}assertNotNull("Expected a recorder START after returning from private recovery",started);assertEquals("beginner:0:private-return",started.getStringExtra("id"));assertFalse(CoachingMemory.data(store).has("checkin"));
  }finally{voice.get().discard();voice.destroy();}
 }

}
